css:
.mda13-compare-wipe{--mda13-cw-p:54%;position:relative;width:100%;max-width:300px;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#dfe8fb;-webkit-user-select:none;user-select:none;}
.mda13-compare-wipe-stage{position:relative;height:96px;border-radius:12px;overflow:hidden;background:#080d18;box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),0 10px 24px -16px #000;}
.mda13-compare-wipe-layer{position:absolute;inset:0;}
.mda13-compare-wipe-before{filter:saturate(.3) contrast(.84) brightness(.9);}
.mda13-compare-wipe-after{filter:saturate(1.28) contrast(1.1) brightness(1.04);}
.mda13-compare-wipe-clip{position:absolute;inset:0;clip-path:inset(0 calc(100% - var(--mda13-cw-p)) 0 0);transition:clip-path .5s cubic-bezier(.22,1,.36,1);}
.mda13-compare-wipe-scene{position:absolute;inset:0;background:radial-gradient(120% 78% at 72% 26%,rgba(255,201,131,.5),rgba(255,150,90,0) 58%),linear-gradient(#0f1a33 0%,#243761 33%,#63658c 51%,#132340 52%,#060c18 100%);}
.mda13-compare-wipe-sun{position:absolute;left:72%;top:26%;width:24px;height:24px;margin:-12px 0 0 -12px;border-radius:50%;background:radial-gradient(circle,#fff4d8 0 34%,#ffc169 58%,rgba(255,170,80,0) 72%);}
.mda13-compare-wipe-ridge{position:absolute;left:0;right:0;bottom:47%;}
.mda13-compare-wipe-far{height:32px;background:#31406c;opacity:.9;clip-path:polygon(0 100%,0 48%,14% 16%,27% 54%,42% 8%,58% 46%,72% 22%,88% 58%,100% 32%,100% 100%);}
.mda13-compare-wipe-near{height:24px;background:#101a30;clip-path:polygon(0 100%,0 64%,12% 38%,30% 76%,46% 30%,64% 72%,80% 44%,100% 74%,100% 100%);}
.mda13-compare-wipe-water{position:absolute;left:0;right:0;bottom:0;height:47%;background:linear-gradient(rgba(255,206,142,.3),rgba(255,206,142,0) 44%),repeating-linear-gradient(0deg,rgba(255,255,255,.07) 0 1px,rgba(255,255,255,0) 1px 5px);}
.mda13-compare-wipe-tag{position:absolute;top:8px;z-index:3;padding:4px 7px;border-radius:999px;font-size:8.5px;font-weight:700;letter-spacing:.1em;text-transform:uppercase;background:rgba(6,10,20,.62);color:#eaf2ff;-webkit-backdrop-filter:blur(5px);backdrop-filter:blur(5px);}
.mda13-compare-wipe-tag-l{left:8px;}
.mda13-compare-wipe-tag-r{right:8px;}
.mda13-compare-wipe-range{position:absolute;inset:0;z-index:5;width:100%;height:100%;margin:0;padding:0;border:0;border-radius:12px;background:transparent;-webkit-appearance:none;appearance:none;cursor:ew-resize;}
.mda13-compare-wipe-range::-webkit-slider-runnable-track{background:transparent;height:100%;}
.mda13-compare-wipe-range::-webkit-slider-thumb{-webkit-appearance:none;width:30px;height:96px;background:transparent;border:0;}
.mda13-compare-wipe-range::-moz-range-track{background:transparent;height:100%;border:0;}
.mda13-compare-wipe-range::-moz-range-thumb{width:30px;height:96px;background:transparent;border:0;border-radius:0;}
.mda13-compare-wipe-range:focus{outline:none;}
.mda13-compare-wipe-range:focus-visible{outline:2px solid #8ed0ff;outline-offset:2px;}
.mda13-compare-wipe-handle{position:absolute;top:0;bottom:0;left:var(--mda13-cw-p);z-index:4;width:2px;margin-left:-1px;pointer-events:none;background:linear-gradient(rgba(233,244,255,.15),#e9f4ff 20%,#e9f4ff 80%,rgba(233,244,255,.15));transition:left .5s cubic-bezier(.22,1,.36,1);}
.mda13-compare-wipe-knob{position:absolute;top:50%;left:50%;width:30px;height:30px;margin:-15px 0 0 -15px;border-radius:50%;display:flex;align-items:center;justify-content:center;gap:4px;background:rgba(10,15,26,.6);border:1.5px solid #e9f4ff;-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);box-shadow:0 6px 16px -6px rgba(0,0,0,.9);transition:transform .32s cubic-bezier(.34,1.56,.64,1);}
.mda13-compare-wipe-arrow{width:0;height:0;border-top:4px solid transparent;border-bottom:4px solid transparent;}
.mda13-compare-wipe-arrow-l{border-right:5px solid #e9f4ff;}
.mda13-compare-wipe-arrow-r{border-left:5px solid #e9f4ff;}
.mda13-compare-wipe-range:hover ~ .mda13-compare-wipe-handle .mda13-compare-wipe-knob{transform:scale(1.14);}
.mda13-compare-wipe-range:active ~ .mda13-compare-wipe-handle .mda13-compare-wipe-knob{transform:scale(.92);}
.mda13-compare-wipe-range:focus-visible ~ .mda13-compare-wipe-handle .mda13-compare-wipe-knob{box-shadow:0 0 0 3px rgba(142,208,255,.35);}
.mda13-compare-wipe-live .mda13-compare-wipe-clip,.mda13-compare-wipe-live .mda13-compare-wipe-handle{transition:none;}
.mda13-compare-wipe-meta{display:flex;align-items:center;justify-content:space-between;margin-top:8px;}
.mda13-compare-wipe-file{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:10px;color:#8697bd;letter-spacing:.01em;}
.mda13-compare-wipe-val{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:10px;font-weight:600;color:#cfe6ff;padding:3px 6px;border-radius:6px;background:rgba(125,211,252,.12);border:1px solid rgba(125,211,252,.24);}
@media (prefers-reduced-motion:reduce){.mda13-compare-wipe-clip,.mda13-compare-wipe-handle,.mda13-compare-wipe-knob{transition:none;}}

js:
var range = root.querySelector('.mda13-compare-wipe-range');
var val = root.querySelector('.mda13-compare-wipe-val');
if (!range || !val) return;
function paint(v){
  var n = Math.max(0, Math.min(100, parseFloat(v) || 0));
  root.style.setProperty('--mda13-cw-p', n + '%');
  val.textContent = Math.round(n) + '%';
}
function live(on){ root.classList.toggle('mda13-compare-wipe-live', !!on); }
paint(range.value);
range.addEventListener('input', function(){ paint(range.value); });
range.addEventListener('pointerdown', function(){ live(true); });
range.addEventListener('pointerup', function(){ live(false); });
range.addEventListener('pointercancel', function(){ live(false); });
range.addEventListener('change', function(){ live(false); });
range.addEventListener('keydown', function(){ live(false); });
range.addEventListener('blur', function(){ live(false); });

css:
.mda13-lightbox-strip{position:relative;width:100%;max-width:300px;min-height:118px;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#e4ebfa;}
.mda13-lightbox-strip-head{display:flex;align-items:baseline;justify-content:space-between;margin-bottom:9px;}
.mda13-lightbox-strip-title{font-size:12px;font-weight:650;letter-spacing:.01em;}
.mda13-lightbox-strip-sub{font-size:9.5px;color:#7f8fb4;}
.mda13-lightbox-strip-row{display:flex;gap:6px;}
.mda13-lightbox-strip-thumb{position:relative;flex:1 1 0;height:44px;padding:0;border:0;border-radius:8px;background:transparent;cursor:pointer;overflow:hidden;transition:transform .28s cubic-bezier(.34,1.56,.64,1),box-shadow .25s ease;}
.mda13-lightbox-strip-thumb:hover{transform:translateY(-3px);box-shadow:0 8px 16px -8px rgba(0,0,0,.95);}
.mda13-lightbox-strip-thumb:active{transform:translateY(-1px) scale(.96);}
.mda13-lightbox-strip-thumb:focus{outline:none;}
.mda13-lightbox-strip-thumb:focus-visible{outline:2px solid #8ed0ff;outline-offset:2px;}
.mda13-lightbox-strip-art{display:block;width:100%;height:100%;border-radius:8px;}
.mda13-lightbox-strip-s1{background:linear-gradient(150deg,#f6c07a,#c9603f 55%,#4a2338);}
.mda13-lightbox-strip-s2{background:linear-gradient(150deg,#d8f0ff,#7fa8cf 50%,#2c3f63);}
.mda13-lightbox-strip-s3{background:linear-gradient(150deg,#8fa1b8,#3d4a63 52%,#141a2a);}
.mda13-lightbox-strip-s4{background:linear-gradient(150deg,#9ef0d8,#3aa78f 52%,#153a44);}
.mda13-lightbox-strip-s5{background:linear-gradient(150deg,#cbe89a,#4f8f56 52%,#16311f);}
.mda13-lightbox-strip-s6{background:linear-gradient(150deg,#a9b6ff,#5747b8 50%,#160f33);}
.mda13-lightbox-strip-hint{margin:9px 0 0;font-size:9px;color:#6d7c9f;letter-spacing:.02em;}
.mda13-lightbox-strip-modal{position:absolute;inset:-6px;z-index:9;display:flex;flex-direction:column;padding:8px;border-radius:14px;background:rgba(6,9,17,.86);-webkit-backdrop-filter:blur(10px);backdrop-filter:blur(10px);opacity:0;transition:opacity .2s ease;}
.mda13-lightbox-strip-modal[hidden]{display:none;}
.mda13-lightbox-strip-open{opacity:1;}
.mda13-lightbox-strip-frame{flex:1 1 auto;min-height:0;border-radius:10px;overflow:hidden;transform:scale(.82);opacity:.2;transition:transform .42s cubic-bezier(.22,1.4,.36,1),opacity .3s ease;}
.mda13-lightbox-strip-open .mda13-lightbox-strip-frame{transform:scale(1);opacity:1;}
.mda13-lightbox-strip-big{border-radius:10px;}
.mda13-lightbox-strip-swap{animation:mda13-lightbox-strip-in .34s cubic-bezier(.22,1,.36,1);}
@keyframes mda13-lightbox-strip-in{from{opacity:0;transform:scale(1.04);}to{opacity:1;transform:scale(1);}}
.mda13-lightbox-strip-cap{display:flex;align-items:baseline;justify-content:space-between;padding:7px 2px 1px;transform:translateY(8px);opacity:0;transition:transform .36s cubic-bezier(.22,1,.36,1) .06s,opacity .3s ease .06s;}
.mda13-lightbox-strip-open .mda13-lightbox-strip-cap{transform:none;opacity:1;}
.mda13-lightbox-strip-name{font-size:11px;font-weight:600;}
.mda13-lightbox-strip-count{font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:9.5px;color:#8ba0c8;}
.mda13-lightbox-strip-nav{position:absolute;top:44%;width:26px;height:26px;margin-top:-13px;padding:0;display:flex;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,.16);border-radius:50%;background:rgba(12,17,28,.7);cursor:pointer;opacity:0;transition:opacity .25s ease,transform .25s cubic-bezier(.34,1.56,.64,1),background .2s ease;}
.mda13-lightbox-strip-open .mda13-lightbox-strip-nav{opacity:1;}
.mda13-lightbox-strip-prev{left:12px;}
.mda13-lightbox-strip-next{right:12px;}
.mda13-lightbox-strip-nav:hover{background:rgba(30,40,60,.9);transform:scale(1.1);}
.mda13-lightbox-strip-nav:active{transform:scale(.9);}
.mda13-lightbox-strip-nav:focus{outline:none;}
.mda13-lightbox-strip-nav:focus-visible{outline:2px solid #8ed0ff;outline-offset:2px;}
.mda13-lightbox-strip-chev{width:6px;height:6px;border-top:1.6px solid #e8f0ff;border-right:1.6px solid #e8f0ff;}
.mda13-lightbox-strip-chev-l{transform:translateX(1px) rotate(-135deg);}
.mda13-lightbox-strip-chev-r{transform:translateX(-1px) rotate(45deg);}
.mda13-lightbox-strip-close{position:absolute;top:10px;right:10px;width:22px;height:22px;padding:0;display:flex;align-items:center;justify-content:center;border:1px solid rgba(255,255,255,.14);border-radius:50%;background:rgba(12,17,28,.72);cursor:pointer;opacity:0;transform:scale(.7);transition:opacity .25s ease .04s,transform .32s cubic-bezier(.34,1.56,.64,1) .04s,background .2s ease;}
.mda13-lightbox-strip-open .mda13-lightbox-strip-close{opacity:1;transform:none;}
.mda13-lightbox-strip-close:hover{background:rgba(214,64,88,.85);}
.mda13-lightbox-strip-close:focus{outline:none;}
.mda13-lightbox-strip-close:focus-visible{outline:2px solid #8ed0ff;outline-offset:2px;}
.mda13-lightbox-strip-x{position:relative;width:9px;height:9px;}
.mda13-lightbox-strip-x::before,.mda13-lightbox-strip-x::after{content:"";position:absolute;top:4px;left:0;width:9px;height:1.5px;border-radius:1px;background:#eef4ff;}
.mda13-lightbox-strip-x::before{transform:rotate(45deg);}
.mda13-lightbox-strip-x::after{transform:rotate(-45deg);}
@media (prefers-reduced-motion:reduce){.mda13-lightbox-strip-thumb,.mda13-lightbox-strip-frame,.mda13-lightbox-strip-cap,.mda13-lightbox-strip-nav,.mda13-lightbox-strip-close,.mda13-lightbox-strip-modal{transition-duration:.01ms;}.mda13-lightbox-strip-swap{animation:none;}}

js:
var thumbs = Array.prototype.slice.call(root.querySelectorAll('.mda13-lightbox-strip-thumb'));
var modal = root.querySelector('.mda13-lightbox-strip-modal');
var big = root.querySelector('.mda13-lightbox-strip-big');
var nameEl = root.querySelector('.mda13-lightbox-strip-name');
var countEl = root.querySelector('.mda13-lightbox-strip-count');
var closeBtn = root.querySelector('.mda13-lightbox-strip-close');
var prevBtn = root.querySelector('.mda13-lightbox-strip-prev');
var nextBtn = root.querySelector('.mda13-lightbox-strip-next');
if (!modal || !big || !thumbs.length) return;
var names = ['Dune ridge','Salt flat','Basalt steps','Low tide','Pine gap','Night camp'];
var idx = 0, opener = null, hideTimer = 0;
function show(n){
  idx = (n + thumbs.length) % thumbs.length;
  big.className = 'mda13-lightbox-strip-big mda13-lightbox-strip-art mda13-lightbox-strip-s' + (idx + 1);
  nameEl.textContent = names[idx] || 'Frame ' + (idx + 1);
  countEl.textContent = (idx + 1) + ' / ' + thumbs.length;
  void big.offsetWidth;
  big.classList.add('mda13-lightbox-strip-swap');
}
function open(n, from){
  window.clearTimeout(hideTimer);
  opener = from || null;
  show(n);
  modal.hidden = false;
  window.requestAnimationFrame(function(){ modal.classList.add('mda13-lightbox-strip-open'); });
  try { closeBtn.focus({ preventScroll: true }); } catch (e) { closeBtn.focus(); }
}
function close(){
  modal.classList.remove('mda13-lightbox-strip-open');
  window.clearTimeout(hideTimer);
  hideTimer = window.setTimeout(function(){ modal.hidden = true; }, 220);
  if (opener) { try { opener.focus({ preventScroll: true }); } catch (e) { opener.focus(); } }
}
thumbs.forEach(function(t, n){ t.addEventListener('click', function(){ open(n, t); }); });
prevBtn.addEventListener('click', function(){ show(idx - 1); });
nextBtn.addEventListener('click', function(){ show(idx + 1); });
closeBtn.addEventListener('click', close);
modal.addEventListener('click', function(e){ if (e.target === modal) close(); });
root.addEventListener('keydown', function(e){
  if (modal.hidden) return;
  if (e.key === 'Escape'){ e.preventDefault(); close(); return; }
  if (e.key === 'ArrowRight'){ e.preventDefault(); show(idx + 1); return; }
  if (e.key === 'ArrowLeft'){ e.preventDefault(); show(idx - 1); return; }
  if (e.key === 'Tab'){
    var ring = [prevBtn, nextBtn, closeBtn];
    var at = ring.indexOf(e.target);
    var next = ring[(at + (e.shiftKey ? ring.length - 1 : 1)) % ring.length];
    if (at > -1){ e.preventDefault(); next.focus(); }
  }
});

var vp = root.querySelector('.mda13-reel-snap-viewport');
var cards = Array.prototype.slice.call(root.querySelectorAll('.mda13-reel-snap-card'));
var dots = Array.prototype.slice.call(root.querySelectorAll('.mda13-reel-snap-dot'));
if (!vp || cards.length < 2) return;
var reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var raf = 0, snapBack = 0, dragging = false, vel = 0, moved = 0;
var startX = 0, startLeft = 0, lastX = 0, lastT = 0;
function stride(){ return Math.max(1, cards[1].offsetLeft - cards[0].offsetLeft); }
function index(){ return Math.max(0, Math.min(cards.length - 1, Math.round(vp.scrollLeft / stride()))); }
function paint(){
  var i = index();
  dots.forEach(function(d, n){
    var on = n === i;
    d.classList.toggle('mda13-reel-snap-on', on);
    d.setAttribute('aria-current', on ? 'true' : 'false');
  });
}
function goTo(i, smooth){
  window.clearTimeout(snapBack);
  vp.style.scrollSnapType = 'none';
  vp.scrollTo({ left: i * stride(), behavior: (smooth && !reduce) ? 'smooth' : 'auto' });
  snapBack = window.setTimeout(function(){ vp.style.scrollSnapType = ''; paint(); }, 380);
}
function settle(){ goTo(index(), true); }
vp.addEventListener('scroll', paint, { passive: true });
vp.addEventListener('pointerdown', function(e){
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  dragging = true; moved = 0; vel = 0;
  window.cancelAnimationFrame(raf); window.clearTimeout(snapBack);
  startX = lastX = e.clientX; lastT = e.timeStamp || Date.now();
  startLeft = vp.scrollLeft;
  vp.style.scrollSnapType = 'none';
  vp.classList.add('mda13-reel-snap-grabbing');
  try { vp.setPointerCapture(e.pointerId); } catch (err) {}
});
vp.addEventListener('pointermove', function(e){
  if (!dragging) return;
  var dx = e.clientX - startX;
  moved = Math.abs(dx);
  if (moved > 3) e.preventDefault();
  vp.scrollLeft = startLeft - dx;
  var t = e.timeStamp || Date.now();
  var dt = Math.max(1, t - lastT);
  vel = ((lastX - e.clientX) / dt) * 16;
  lastX = e.clientX; lastT = t;
});
function release(e){
  if (!dragging) return;
  dragging = false;
  vp.classList.remove('mda13-reel-snap-grabbing');
  try { vp.releasePointerCapture(e.pointerId); } catch (err) {}
  if (reduce || Math.abs(vel) < 1.2){ settle(); return; }
  var max = vp.scrollWidth - vp.clientWidth;
  var glide = function(){
    vel *= 0.93;
    vp.scrollLeft += vel;
    if (Math.abs(vel) > 0.4 && vp.scrollLeft > 0.5 && vp.scrollLeft < max - 0.5){ raf = window.requestAnimationFrame(glide); }
    else { settle(); }
  };
  raf = window.requestAnimationFrame(glide);
}
vp.addEventListener('pointerup', release);
vp.addEventListener('pointercancel', release);
vp.addEventListener('click', function(e){ if (moved > 6){ e.preventDefault(); e.stopPropagation(); } }, true);
dots.forEach(function(d, n){ d.addEventListener('click', function(){ goTo(n, true); }); });
paint();

