.mda13-wave-scrub{--mda13-ws-p:0%;--mda13-ws-i:0;width:100%;max-width:300px;font-family:ui-sans-serif,system-ui,-apple-system,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;color:#e4ebfa;-webkit-user-select:none;user-select:none;}
.mda13-wave-scrub-row{display:flex;align-items:center;gap:9px;}
.mda13-wave-scrub-play{position:relative;flex:0 0 auto;width:34px;height:34px;padding:0;border:0;border-radius:50%;cursor:pointer;background:linear-gradient(150deg,#6ee7c4,#3b93f0);box-shadow:0 6px 16px -8px rgba(78,168,240,.9);transition:transform .28s cubic-bezier(.34,1.56,.64,1),box-shadow .25s ease;}
.mda13-wave-scrub-play:hover{transform:scale(1.07);}
.mda13-wave-scrub-play:active{transform:scale(.93);}
.mda13-wave-scrub-play:focus{outline:none;}
.mda13-wave-scrub-play:focus-visible{outline:2px solid #8ed0ff;outline-offset:3px;}
.mda13-wave-scrub-tri{position:absolute;top:50%;left:50%;width:0;height:0;margin:-6px 0 0 -4px;border-top:6px solid transparent;border-bottom:6px solid transparent;border-left:10px solid #06131f;transition:opacity .22s ease,transform .32s cubic-bezier(.34,1.56,.64,1);}
.mda13-wave-scrub-pause{position:absolute;top:50%;left:50%;display:flex;gap:3px;margin:-6px 0 0 -5px;opacity:0;transform:scale(.6) rotate(-30deg);transition:opacity .22s ease,transform .32s cubic-bezier(.34,1.56,.64,1);}
.mda13-wave-scrub-p1,.mda13-wave-scrub-p2{width:3.5px;height:12px;border-radius:1.5px;background:#06131f;}
.mda13-wave-scrub-playing .mda13-wave-scrub-tri{opacity:0;transform:scale(.6) rotate(30deg);}
.mda13-wave-scrub-playing .mda13-wave-scrub-pause{opacity:1;transform:none;}
.mda13-wave-scrub-info{display:flex;flex-direction:column;gap:2px;min-width:0;flex:1 1 auto;}
.mda13-wave-scrub-name{font-size:11.5px;font-weight:620;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.mda13-wave-scrub-meta{font-size:9.5px;color:#7d8db1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.mda13-wave-scrub-clock{flex:0 0 auto;font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;font-size:9.5px;color:#8ba0c8;}
.mda13-wave-scrub-cur{color:#d7e6ff;}
.mda13-wave-scrub-wave{position:relative;height:46px;margin-top:11px;border-radius:8px;cursor:pointer;touch-action:none;}
.mda13-wave-scrub-wave:focus{outline:none;}
.mda13-wave-scrub-wave:focus-visible{outline:2px solid #8ed0ff;outline-offset:3px;}
.mda13-wave-scrub-bars{position:absolute;inset:0;display:flex;align-items:center;gap:1.5px;}
.mda13-wave-scrub-bar{flex:1 1 0;min-width:0;border-radius:1.5px;background:#2f3a56;transform-origin:50% 50%;transition:background .3s ease;}
.mda13-wave-scrub-veil{position:absolute;inset:0;clip-path:inset(0 calc(100% - var(--mda13-ws-p)) 0 0);transition:clip-path .12s linear;}
.mda13-wave-scrub-fill .mda13-wave-scrub-bar{background:linear-gradient(180deg,#7defcf,#4aa2f5);}
.mda13-wave-scrub-wave:hover .mda13-wave-scrub-base .mda13-wave-scrub-bar{background:#3a4767;}
.mda13-wave-scrub-playing .mda13-wave-scrub-base .mda13-wave-scrub-bar{animation:mda13-wave-scrub-pulse 1.5s ease-in-out infinite;animation-delay:calc(var(--mda13-ws-i) * 26ms);}
