var base = root.querySelector('.mda13-wave-scrub-base');
var fill = root.querySelector('.mda13-wave-scrub-fill');
var wave = root.querySelector('.mda13-wave-scrub-wave');
var btn = root.querySelector('.mda13-wave-scrub-play');
var curEl = root.querySelector('.mda13-wave-scrub-cur');
if (!base || !fill || !wave || !btn) return;
var N = 52, markup = '';
for (var k = 0; k < N; k++){
  var t = k / (N - 1);
  var env = 0.42 + 0.58 * Math.sin(Math.PI * Math.pow(t, 0.85));
  var h = (26 + Math.abs(Math.sin(k * 0.79)) * 40 + Math.abs(Math.sin(k * 0.23 + 1.1)) * 30) * env;
  h = Math.max(12, Math.min(100, h));
  markup += '<span class="mda13-wave-scrub-bar" style="height:' + h.toFixed(1) + '%;--mda13-ws-i:' + k + '"></span>';
}
base.innerHTML = markup;
fill.innerHTML = markup;
var dur = 38, cur = 0, playing = false, last = 0, raf = 0;
function fmt(s){ s = Math.max(0, Math.floor(s)); return Math.floor(s / 60) + ':' + ('0' + (s % 60)).slice(-2); }
function render(){
  root.style.setProperty('--mda13-ws-p', ((cur / dur) * 100).toFixed(2) + '%');
  curEl.textContent = fmt(cur);
  wave.setAttribute('aria-valuenow', String(Math.round(cur)));
  wave.setAttribute('aria-valuetext', fmt(cur) + ' of ' + fmt(dur));
}
function tick(t){
  if (!playing) return;
  if (!last) last = t;
  cur += (t - last) / 1000;
  last = t;
  if (cur >= dur){ cur = dur; render(); setPlaying(false); return; }
  render();
  raf = window.requestAnimationFrame(tick);
}
function setPlaying(on){
  playing = !!on;
  last = 0;
  window.cancelAnimationFrame(raf);
  root.classList.toggle('mda13-wave-scrub-playing', playing);
  btn.setAttribute('aria-pressed', playing ? 'true' : 'false');
  btn.setAttribute('aria-label', playing ? 'Pause voice note' : 'Play voice note');
  if (playing){ if (cur >= dur) cur = 0; raf = window.requestAnimationFrame(tick); }
}
btn.addEventListener('click', function(){ setPlaying(!playing); });
function seekFrom(clientX){
  var r = wave.getBoundingClientRect();
  var ratio = Math.max(0, Math.min(1, (clientX - r.left) / Math.max(1, r.width)));
  cur = ratio * dur;
  render();
}
var scrubbing = false;
wave.addEventListener('pointerdown', function(e){
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  scrubbing = true;
  try { wave.setPointerCapture(e.pointerId); } catch (err) {}
  seekFrom(e.clientX);
});
wave.addEventListener('pointermove', function(e){ if (scrubbing){ e.preventDefault(); seekFrom(e.clientX); } });
wave.addEventListener('pointerup', function(e){ scrubbing = false; try { wave.releasePointerCapture(e.pointerId); } catch (err) {} });
wave.addEventListener('pointercancel', function(){ scrubbing = false; });
wave.addEventListener('keydown', function(e){
  var step = e.shiftKey ? 5 : 2;
  if (e.key === 'ArrowRight'){ cur = Math.min(dur, cur + step); }
  else if (e.key === 'ArrowLeft'){ cur = Math.max(0, cur - step); }
  else if (e.key === 'Home'){ cur = 0; }
  else if (e.key === 'End'){ cur = dur; }
  else { return; }
  e.preventDefault();
  render();
});
render();

