var rail = root.querySelector('.mda13-video-chrome-rail');
var bigBtn = root.querySelector('.mda13-video-chrome-big');
var toggle = root.querySelector('.mda13-video-chrome-toggle');
var muteBtn = root.querySelector('.mda13-video-chrome-mute');
var wideBtn = root.querySelector('.mda13-video-chrome-wide');
var curEl = root.querySelector('.mda13-video-chrome-cur');
var tipTime = root.querySelector('.mda13-video-chrome-tiptime');
var tipArt = root.querySelector('.mda13-video-chrome-tipart');
if (!rail || !stage) return;
var dur = 48, cur = 0, playing = false, last = 0, raf = 0, buf = 34, idleTimer = 0;
function armIdle(){
  window.clearTimeout(idleTimer);
  root.classList.remove('mda13-video-chrome-idle');
  if (playing) idleTimer = window.setTimeout(function(){ root.classList.add('mda13-video-chrome-idle'); }, 2200);
}
stage.addEventListener('pointermove', armIdle);
stage.addEventListener('pointerdown', armIdle);
stage.addEventListener('pointerleave', function(){ if (playing){ window.clearTimeout(idleTimer); root.classList.add('mda13-video-chrome-idle'); } });
function fmt(s){ s = Math.max(0, Math.floor(s)); return Math.floor(s / 60) + ':' + ('0' + (s % 60)).slice(-2); }
function render(){
  var p = (cur / dur) * 100;
  root.style.setProperty('--mda13-vc-p', p.toFixed(2) + '%');
  buf = Math.min(100, Math.max(buf, p + 16));
  root.style.setProperty('--mda13-vc-b', buf.toFixed(2) + '%');
  curEl.textContent = fmt(cur);
  rail.setAttribute('aria-valuenow', String(Math.round(cur)));
  rail.setAttribute('aria-valuetext', fmt(cur) + ' of ' + fmt(dur));
}
function tick(t){
  if (!playing) return;
  if (!last) last = t;
  cur += (t - last) / 1000;
  last = t;
  if (cur >= dur){ cur = dur; render(); setPlaying(false); return; }
  render();
  raf = window.requestAnimationFrame(tick);
}
function setPlaying(on){
  playing = !!on;
  last = 0;
  window.cancelAnimationFrame(raf);
  root.classList.toggle('mda13-video-chrome-playing', playing);
  bigBtn.setAttribute('aria-label', playing ? 'Pause video' : 'Play video');
  toggle.setAttribute('aria-label', playing ? 'Pause' : 'Play');
  if (playing){ if (cur >= dur){ cur = 0; buf = 20; } raf = window.requestAnimationFrame(tick); }
  armIdle();
}
bigBtn.addEventListener('click', function(){ setPlaying(!playing); });
toggle.addEventListener('click', function(){ setPlaying(!playing); });
muteBtn.addEventListener('click', function(){
  var on = muteBtn.getAttribute('aria-pressed') === 'true';
  muteBtn.setAttribute('aria-pressed', on ? 'false' : 'true');
  muteBtn.setAttribute('aria-label', on ? 'Mute' : 'Unmute');
  root.classList.toggle('mda13-video-chrome-muted', !on);
});
wideBtn.addEventListener('click', function(){
  var on = wideBtn.getAttribute('aria-pressed') === 'true';
  wideBtn.setAttribute('aria-pressed', on ? 'false' : 'true');
  root.classList.toggle('mda13-video-chrome-theater', !on);
});
function ratioFrom(clientX){
  var r = rail.getBoundingClientRect();
  return Math.max(0, Math.min(1, (clientX - r.left) / Math.max(1, r.width)));
}
var scrubbing = false;
rail.addEventListener('pointerdown', function(e){
  if (e.pointerType === 'mouse' && e.button !== 0) return;
  scrubbing = true;
  try { rail.setPointerCapture(e.pointerId); } catch (err) {}
  cur = ratioFrom(e.clientX) * dur;
  render();
});
rail.addEventListener('pointermove', function(e){
  var ratio = ratioFrom(e.clientX);
  root.style.setProperty('--mda13-vc-tip', (ratio * 100).toFixed(2) + '%');
  tipTime.textContent = fmt(ratio * dur);
  tipArt.style.backgroundPosition = (ratio * 100).toFixed(0) + '% 50%';
  if (scrubbing){ e.preventDefault(); cur = ratio * dur; render(); }
});
rail.addEventListener('pointerup', function(e){ scrubbing = false; try { rail.releasePointerCapture(e.pointerId); } catch (err) {} });
rail.addEventListener('pointercancel', function(){ scrubbing = false; });
