js:
var btn = root.querySelector('.mda13-avatar-ring-btn');
var state = root.querySelector('.mda13-avatar-ring-state');
var opts = Array.prototype.slice.call(root.querySelectorAll('.mda13-avatar-ring-opt'));
if (!btn || !state) return;
var labels = { online: 'Online', away: 'Away', busy: 'Do not disturb' };
var flashTimer = 0;
function describe(){
  var s = root.getAttribute('data-status') || 'online';
  var seen = root.getAttribute('data-story') === 'seen';
  state.textContent = (labels[s] || 'Online') + ' · ' + (seen ? 'story seen' : 'new story');
  btn.setAttribute('aria-label', (seen ? 'Replay story from' : 'Open new story from') + ' Priya Raman');
}
btn.addEventListener('click', function(){
  var seen = root.getAttribute('data-story') === 'seen';
  root.setAttribute('data-story', seen ? 'new' : 'seen');
  if (!seen){
    root.classList.remove('mda13-avatar-ring-flash');
    void btn.offsetWidth;
    root.classList.add('mda13-avatar-ring-flash');
    window.clearTimeout(flashTimer);
    flashTimer = window.setTimeout(function(){ root.classList.remove('mda13-avatar-ring-flash'); }, 760);
  }
  describe();
});
opts.forEach(function(o, i){
  o.addEventListener('click', function(){
    opts.forEach(function(x){ x.setAttribute('aria-pressed', x === o ? 'true' : 'false'); });
    root.style.setProperty('--mda13-ar-i', String(i));
    root.setAttribute('data-status', o.getAttribute('data-mda13-status') || 'online');
    describe();
  });
});
describe();

