.mda13-drop-ring[data-state="busy"] .mda13-drop-ring-arrow,.mda13-drop-ring[data-state="done"] .mda13-drop-ring-arrow,.mda13-drop-ring[data-state="error"] .mda13-drop-ring-arrow{opacity:0;}
