js:
var zone = root.querySelector('.mda13-drop-ring-zone');
var input = root.querySelector('.mda13-drop-ring-input');
var arc = root.querySelector('.mda13-drop-ring-arc');
var pct = root.querySelector('.mda13-drop-ring-pct');
var title = root.querySelector('.mda13-drop-ring-title');
var sub = root.querySelector('.mda13-drop-ring-sub');
var act = root.querySelector('.mda13-drop-ring-act');
var live = root.querySelector('.mda13-drop-ring-live');
if (!zone || !input || !arc) return;
var C = 2 * Math.PI * 26;
arc.style.strokeDasharray = C.toFixed(2);
var timer = 0;
function setProgress(p){
  arc.style.strokeDashoffset = (C * (1 - Math.max(0, Math.min(1, p)))).toFixed(2);
  pct.textContent = Math.round(p * 100) + '%';
}
function setState(s, action){
  root.setAttribute('data-state', s);
  act.textContent = action;
}
function size(bytes){
  if (!bytes && bytes !== 0) return 'unknown size';
  if (bytes < 1048576) return (bytes / 1024).toFixed(0) + ' KB';
  if (bytes < 1073741824) return (bytes / 1048576).toFixed(1) + ' MB';
  return (bytes / 1073741824).toFixed(2) + ' GB';
}
function clip(name){ return name.length > 24 ? name.slice(0, 22) + '…' : name; }
function reset(){
  window.clearInterval(timer);
  setProgress(0);
  setState('idle', 'Browse files');
  prevState = 'idle';
  title.textContent = 'Drop footage here';
  sub.textContent = 'MP4 or MOV · up to 2 GB';
  live.textContent = 'Ready to upload';
  input.value = '';
}
var lastFile = null, prevState = 'idle';
function start(file){
  if (!file) return;
  lastFile = file;
  window.clearInterval(timer);
  setProgress(0);
  title.textContent = clip(file.name);
  var ok = /^video\//.test(file.type || '') || /\.(mp4|mov|m4v)$/i.test(file.name);
  if (!ok){
    setState('error', 'Choose another');
    sub.textContent = 'Needs MP4 or MOV';
    live.textContent = 'Rejected: unsupported format';
    return;
  }
  sub.textContent = size(file.size) + ' · uploading';
  setState('busy', 'Cancel');
  live.textContent = 'Uploading ' + clip(file.name);
  var p = 0;
  timer = window.setInterval(function(){
    p += 0.02 + Math.random() * 0.05;
    if (p >= 1){
      window.clearInterval(timer);
      setProgress(1);
      setState('done', 'Add another');
      sub.textContent = size(file.size) + ' · in library';
      live.textContent = 'Upload complete';
      return;
    }
    setProgress(p);
  }, 90);
}
act.addEventListener('click', function(){
  var s = root.getAttribute('data-state');
  if (s === 'busy'){ reset(); live.textContent = 'Upload cancelled'; return; }
  if (s === 'error' && lastFile){ input.value = ''; }
  input.click();
});
input.addEventListener('change', function(){ if (input.files && input.files[0]) start(input.files[0]); });
zone.addEventListener('dragenter', function(e){
  e.preventDefault();
  var s = root.getAttribute('data-state');
  if (s === 'busy' || s === 'over') return;
  prevState = s;
  root.setAttribute('data-state', 'over');
});
zone.addEventListener('dragover', function(e){
  e.preventDefault();
  if (e.dataTransfer) e.dataTransfer.dropEffect = 'copy';
});
zone.addEventListener('dragleave', function(e){
  if (zone.contains(e.relatedTarget)) return;
  if (root.getAttribute('data-state') === 'over') root.setAttribute('data-state', prevState);
});
zone.addEventListener('drop', function(e){
  e.preventDefault();
  if (root.getAttribute('data-state') === 'over') root.setAttribute('data-state', prevState);
  var files = e.dataTransfer && e.dataTransfer.files;
  if (files && files[0]) start(files[0]);
});
reset();
